package lsp

import "errors"

// PROBLEM
//
// Two stores below both fit the Store interface, and the compiler accepts
// both. But one of them breaks a promise: asked for a key that was never
// stored, it says "here you go" (an empty value, no error) instead of
// ErrNotFound. Code that relies on ErrNotFound now misbehaves, and nothing
// warns you. The compiler checks names and types, not promises.
//
// TRY IT
//
// Read TestBefore_LyingStoreHidesMissingKeys in lsp_test.go. The honest store
// returns ErrNotFound for a missing key. The lying store returns ("", nil).
//
// Do not edit this file. Your work goes in after.go.

// ErrNotFound is part of the Store contract, not an implementation detail.
var ErrNotFound = errors.New("not found")

// Store is a string key-value store.
//
// The contract. Every implementation must keep all five promises:
//  1. Get on a key that was never stored returns ErrNotFound.
//  2. Put on a healthy store succeeds.
//  3. After Put(k, v), Get(k) returns v.
//  4. Put on an existing key succeeds (it overwrites).
//  5. After overwriting, Get returns the newest value.
type Store interface {
	Get(key string) (string, error)
	Put(key, value string) error
}

// goodStore keeps every promise in the Store contract.
type goodStore struct{ m map[string]string }

// NewGood returns an empty store that keeps the contract.
func NewGood() Store { return &goodStore{m: map[string]string{}} }

func (s *goodStore) Get(key string) (string, error) {
	v, ok := s.m[key]
	if !ok {
		return "", ErrNotFound
	}
	return v, nil
}

func (s *goodStore) Put(key, value string) error {
	s.m[key] = value
	return nil
}

// lyingStore compiles and satisfies Store, but breaks promise 1: a missing
// key comes back as ("", nil) instead of ErrNotFound.
type lyingStore struct{ m map[string]string }

// NewLying returns an empty store that breaks the contract.
func NewLying() Store { return &lyingStore{m: map[string]string{}} }

func (s *lyingStore) Get(key string) (string, error) {
	return s.m[key], nil
}

func (s *lyingStore) Put(key, value string) error {
	s.m[key] = value
	return nil
}

// The compiler accepts both. That is the point of this lesson.
var (
	_ Store = (*goodStore)(nil)
	_ Store = (*lyingStore)(nil)
)
